globalCss`
@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}
@keyframes pulse {
  50% {
    opacity: 0.5;
  }
}
@keyframes enter {
  from {
    opacity: var(--ui-enter-opacity,1);
    transform: translate3d(var(--ui-enter-translate-x,0),var(--ui-enter-translate-y,0),0)scale3d(var(--ui-enter-scale,1),var(--ui-enter-scale,1),var(--ui-enter-scale,1))rotate(var(--ui-enter-rotate,0));
    filter: blur(var(--ui-enter-blur,0));
  }
}
@keyframes exit {
  to {
    opacity: var(--ui-exit-opacity,1);
    transform: translate3d(var(--ui-exit-translate-x,0),var(--ui-exit-translate-y,0),0)scale3d(var(--ui-exit-scale,1),var(--ui-exit-scale,1),var(--ui-exit-scale,1))rotate(var(--ui-exit-rotate,0));
    filter: blur(var(--ui-exit-blur,0));
  }
}
@keyframes caret-blink {
  0%,70%,100% {
    opacity: 1;
  }
  20%,50% {
    opacity: 0;
  }
